"use client";
import {useActionState,useState} from "react";
import {FileUp,Save} from "lucide-react";
import {ContextFileInput} from "@/components/context-file-input";
import {importStructure} from "@/app/app/people/structure-actions";
type Row={name:string;department:string;managerName:string;person:string;manager:string;include:boolean};
export function StructureImport({id,members}:{id:string;members:Array<{id:string;name:string}>}) {
 const[content,setContent]=useState(""),[source,setSource]=useState(""),[rows,setRows]=useState<Row[]>([]),[uncertainties,setUncertainties]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const[state,action,pending]=useActionState(importStructure,{});
 async function prepare(){setBusy(true);setError("");try{const response=await fetch("/api/company/structure-draft",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({content})});const data=await response.json();if(!response.ok)throw new Error(data.error);setRows(data.rows.map((r:Pick<Row,"name"|"department"|"managerName">)=>({...r,person:"",manager:"",include:false})));setUncertainties(data.uncertainties);}catch(e){setError(e instanceof Error?e.message:"Draft could not be prepared.");}finally{setBusy(false);}}
 const update=(i:number,patch:Partial<Row>)=>setRows(current=>current.map((r,index)=>index===i?{...r,...patch}:r));
 return <details className="company-document"><summary>Import an organisation chart</summary><div className="stack-form"><ContextFileInput purpose="structure" disabled={busy||pending} onExtract={(text,name)=>{setContent(text);setSource(name);setRows([]);}}/><label>Source name<input value={source} onChange={e=>setSource(e.target.value)} maxLength={300}/></label><label>Chart text<textarea value={content} onChange={e=>setContent(e.target.value)} maxLength={24000} rows={6}/></label><button type="button" className="button button-quiet" disabled={busy||content.trim().length<20} onClick={()=>void prepare()}><FileUp size={16}/>{busy?"Preparing draft...":"Prepare review draft"}</button>{error&&<p role="alert">{error}</p>}{uncertainties&&<p className="form-message">{uncertainties}</p>}</div>
 {!!rows.length&&<form action={action} className="stack-form"><input type="hidden" name="id" value={id}/><input type="hidden" name="source" value={source}/><input type="hidden" name="rows" value={JSON.stringify(rows.filter(r=>r.include).map(r=>({person:r.person,department:r.department,manager:r.manager})))}/><p className="role-note">Select only confirmed placements. Unmatched people stay out of this import; invite them through People. Heads and permissions are not inferred.</p>{rows.map((r,i)=><fieldset className="company-document stack-form" key={i}><legend>{r.name||`Person ${i+1}`}</legend><label className="company-checkbox"><input type="checkbox" checked={r.include} onChange={e=>update(i,{include:e.target.checked})}/>Include this placement</label><label>Existing member<select value={r.person} required={r.include} onChange={e=>update(i,{person:e.target.value})}><option value="">Match an existing person</option>{members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label>Department<input value={r.department} required={r.include} minLength={2} maxLength={100} onChange={e=>update(i,{department:e.target.value})}/></label><label>Reports to{r.managerName&&<small>Source names: {r.managerName}</small>}<select value={r.manager} onChange={e=>update(i,{manager:e.target.value})}><option value="">Not specified</option>{members.filter(m=>m.id!==r.person).map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label></fieldset>)}{state.error&&<p role="alert">{state.error}</p>}{state.success&&<p role="status">{state.success}</p>}<button className="button button-primary" disabled={pending||Boolean(state.success)||!rows.some(r=>r.include)}><Save size={16}/>Confirm selected placements</button></form>}</details>;
}
