"use client";
import {useActionState} from "react";
import {Check,RefreshCw,Save,X} from "lucide-react";
import {checkSource,reviewSource,saveSource} from "@/app/app/company/source-actions";
import type {CompanyState} from "@/app/app/company/actions";
export type Source={id:string;label:string;url:string;cadence:string;status:string;checked_at:string|null};
function Result({state}:{state:CompanyState}){return <>{state.error&&<p className="form-message" role="alert">{state.error}</p>}{state.success&&<p className="form-message success" role="status">{state.success}</p>}</>;}
export function SourceForm({source}:{source?:Source}){const[state,action,pending]=useActionState(saveSource,{});return <form action={action} className="stack-form"><input type="hidden" name="id" value={source?.id||""}/><label>Source name<input name="label" required minLength={2} maxLength={120} defaultValue={source?.label||""}/></label><label>Public URL<input name="url" type="url" required maxLength={2000} defaultValue={source?.url||""} readOnly={Boolean(source)}/></label><label>Refresh<select name="cadence" defaultValue={source?.cadence||"manual"}><option value="manual">Only when requested</option><option value="daily">Daily checks</option><option value="weekly">Weekly checks</option><option value="reference">Reference link only</option></select></label><Result state={state}/><button className="button button-primary" disabled={pending}><Save size={16}/>Save source</button></form>;}
export function SourceRefresh({id}:{id:string}){const[state,action,pending]=useActionState(checkSource,{});return <form action={action}><input type="hidden" name="id" value={id}/><button className="button button-quiet" disabled={pending}><RefreshCw size={16}/>{pending?"Checking...":"Check source now"}</button><Result state={state}/></form>;}
export function SourceReview({id}:{id:string}){const[state,action,pending]=useActionState(reviewSource,{});return <form action={action}><input type="hidden" name="id" value={id}/><div className="page-actions"><button name="decision" value="approved" className="button button-primary" disabled={pending}><Check size={16}/>Approve as company context</button><button name="decision" value="rejected" className="button button-quiet" disabled={pending}><X size={16}/>Exclude</button></div><Result state={state}/></form>;}
